<?php require '../config/database.php'; require '../includes/functions.php'; require_admin(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$pdo->prepare("INSERT INTO products(name,category,description,price,condition_label,status) VALUES(?,?,?,?,?,'available')"); $q->execute([trim($_POST['name']),trim($_POST['category']),trim($_POST['description']), (float)$_POST['price'],trim($_POST['condition_label'])]); } $rows=$pdo->query("SELECT * FROM products ORDER BY created_at DESC")->fetchAll(); site_header('Manage Products'); ?>
<div class="admin-wrap"><h1>Manage Products</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="bookings.php">Bookings</a><a href="messages.php">Messages</a><a href="products.php">Products</a><a href="opportunities.php">Opportunities</a><a href="logout.php">Logout</a></nav><form class="form-card" method="post"><h2>Add product</h2><div class="form-grid"><div class="field"><label>Product name</label><input name="name" required></div><div class="field"><label>Category</label><input name="category" required></div><div class="field"><label>Price (RWF)</label><input type="number" name="price" min="0" step="1" required></div><div class="field"><label>Condition</label><select name="condition_label"><option>New</option><option>Used</option><option>Refurbished</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div></div><button class="btn">Add product</button></form><h2>Product listings</h2><div class="table-wrap"><table><tr><th>Name</th><th>Category</th><th>Price</th><th>Status</th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['category'])?></td><td><?=number_format($r['price'])?> RWF</td><td><?=e($r['status'])?></td></tr><?php endforeach; ?></table></div></div><?php site_footer(); ?>